77	static String jstr(JsonVariantConst o, const char* a, const char* b = nullptr) {
78	  JsonVariantConst v = o[a];
79	  if (v.isNull() && b) v = o[b];
80	  if (v.isNull()) return "";
81	  return v.as<String>();
82	}
