84	static bool fetchQuotes() {
85	  if (WiFi.status() != WL_CONNECTED) return false;
86	  WiFiClientSecure cli;
87	  cli.setInsecure();
88	  HTTPClient http;
89	  http.setTimeout(10000);
90	  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
91	  if (!http.begin(cli, API_URL)) return false;
92	  int code = http.GET();
93	  if (code != 200) {
94	    Serial.printf("[api] HTTP %d\n", code);
95	    http.end();
96	    return false;
97	  }
98	  String body = http.getString();
99	  http.end();
100	  JsonDocument doc;
101	  if (deserializeJson(doc, body)) return false;
102	
103	  int added = 0;
104	  auto parseOne = [&](JsonVariantConst o) {
105	    Quote q;
106	    q.idx = jstr(o, "idx");
107	    q.content = jstr(o, "content", "main_content");
108	    if (q.content.length() == 0) return;
109	    q.context = jstr(o, "context");
110	    q.date = jstr(o, "date", "effectiveDate");
111	    q.specific = jstr(o, "specific", "specificName");
112	    q.container = jstr(o, "container", "containerName");
113	    q.cat = jstr(o, "cat", "category");
114	    JsonVariantConst tg = o["tags"].isNull() ? o["hashtagThemes"] : o["tags"];
115	    if (tg.is<JsonArrayConst>()) {
116	      for (JsonVariantConst t : tg.as<JsonArrayConst>()) {
117	        String s = t.as<String>();
118	        if (!s.startsWith("#")) s = "#" + s;
119	        q.tags.push_back(s);
120	      }
121	    }
122	    // Prevent duplicate quote entries in RAM
123	    for (const auto& existing : quotes) {
124	      if (existing.idx == q.idx) return;
125	    }
126	    quotes.push_back(q);
127	    added++;
128	  };
129	
130	  if (doc.is<JsonArray>()) for (JsonVariantConst o : doc.as<JsonArray>()) parseOne(o);
131	  else parseOne(doc.as<JsonVariantConst>());
132	
133	  // Purge temporary offline standby card once genuine cloud quotes are received
134	  if (added > 0 && !quotes.empty() && quotes[0].idx == "!") {
135	    quotes.erase(quotes.begin());
136	  }
137	
138	  // Limit pool size in RAM to max 20 quotes to bound heap consumption
139	  while (quotes.size() > 20) {
140	    quotes.erase(quotes.begin());
141	  }
142	
143	  Serial.printf("[api] Cloudflare stream: +%d quotes (RAM pool: %d)\n", added, (int)quotes.size());
144	  return added > 0;
145	}
