147	// ------------------------------------------------------------------ utf-8
148	static std::u16string u8to16(const String& s) {
149	  std::u16string o;
150	  const uint8_t* p = (const uint8_t*)s.c_str();
151	  size_t n = s.length();
152	  for (size_t i = 0; i < n;) {
153	    uint8_t c = p[i];
154	    uint32_t cp;
155	    int len;
156	    if (c < 0x80) { cp = c; len = 1; }
157	    else if ((c >> 5) == 6) { cp = c & 0x1F; len = 2; }
158	    else if ((c >> 4) == 14) { cp = c & 0x0F; len = 3; }
159	    else if ((c >> 3) == 30) { cp = c & 0x07; len = 4; }
160	    else { i++; continue; }
161	    if (i + len > n) break;
162	    for (int k = 1; k < len; k++) cp = (cp << 6) | (p[i + k] & 0x3F);
163	    i += len;
164	    o.push_back(cp > 0xFFFF ? u'?' : (char16_t)cp);
165	  }
166	  return o;
167	}
