173	static bool isWS(char16_t c) { return c == ' ' || c == '\t' || c == '\r' || c == 0xA0; }
174	
175	static void tokenize(const std::u16string& s, std::vector<std::u16string>& tok) {
176	  std::u16string w;
177	  auto flush = [&]() { if (!w.empty()) { tok.push_back(w); w.clear(); } };
178	  for (char16_t c : s) {
179	    if (c == '\n') { flush(); tok.push_back(u"\n"); }
180	    else if (isWS(c)) flush();
181	    else w.push_back(c);
182	  }
183	  flush();
184	}
185	
186	static std::u16string trim16(const std::u16string& s) {
187	  size_t a = 0, b = s.size();
188	  while (a < b && (isWS(s[a]) || s[a] == '\n')) a++;
189	  while (b > a && (isWS(s[b - 1]) || s[b - 1] == '\n')) b--;
190	  return s.substr(a, b - a);
191	}
192	
193	static bool isWriting(const String& cat) {
194	  String c = cat; c.trim(); c.toLowerCase();
195	  return c == "writing" || c == "bài viết" || c == "baiviet";
196	}
