198	static std::vector<Page> buildPages(const Quote& q) {
199	  std::vector<Page> pages;
200	  std::u16string content = trim16(u8to16(q.content));
201	  if (content.empty()) { pages.push_back({{{u"", false}}, false}); return pages; }
202	  std::vector<std::u16string> tok;
203	  tokenize(content, tok);
204	  bool writing = isWriting(q.cat);
205	  size_t ti = 0;
206	  int pageNum = 0;
207	  while (ti < tok.size()) {
208	    pageNum++;
209	    bool first = pageNum == 1;
210	    std::vector<std::u16string> pl;
211	    for (int ln = 1; ln <= MAX_LINES && ti < tok.size(); ln++) {
212	      int budget = MAX_CHARS;
213	      if (first && ln == 1) budget = MAX_CHARS - 1;
214	      if (ln == MAX_LINES) budget = MAX_CHARS - 4;
215	      std::u16string cur;
216	      while (ti < tok.size()) {
217	        const std::u16string& nt = tok[ti];
218	        if (nt == u"\n") { ti++; break; }
219	        if (cur.empty()) { cur = nt; ti++; }
220	        else if ((int)(cur.size() + 1 + nt.size()) <= budget) { cur += u" "; cur += nt; ti++; }
221	        else break;
222	      }
223	      pl.push_back(cur);
224	    }
225	    size_t la = ti;
226	    while (la < tok.size() && tok[la] == u"\n") la++;
227	    bool more = la < tok.size();
228	    if (first && !pl.empty()) pl[0] = u"\u201C" + pl[0];
229	    if (more) pl.back() += u"...";
230	    else pl.back() += u"\u201D";
231	    Page pg; pg.ctx = false;
232	    for (size_t i = 0; i < pl.size(); i++) {
233	      bool terminal = !more && i == pl.size() - 1;
234	      bool just = writing && !terminal && pl[i].find(u' ') != std::u16string::npos;
235	      if (!trim16(pl[i]).empty()) pg.lines.push_back({pl[i], just});
236	    }
237	    pages.push_back(pg);
238	  }
239	  // context pages
240	  if (q.context.length() > 0) {
241	    std::vector<std::u16string> cw;
242	    tokenize(u8to16(q.context), cw);
243	    size_t ci = 0;
244	    bool firstCtx = true;
245	    while (ci < cw.size()) {
246	      std::vector<std::u16string> cl;
247	      for (int l = 1; l <= MAX_LINES && ci < cw.size(); l++) {
248	        int budget = (l == MAX_LINES) ? MAX_CHARS - 4 : MAX_CHARS;
249	        std::u16string cur;
250	        if (firstCtx && l == 1) { cur = u"[Note] "; firstCtx = false; }
251	        while (ci < cw.size()) {
252	          if (cw[ci] == u"\n") { ci++; continue; }
253	          if (cur.empty()) { cur = cw[ci]; ci++; }
254	          else if ((int)(cur.size() + 1 + cw[ci].size()) <= budget || cur == u"[Note] ") {
255	            if (cur != u"[Note] ") cur += u" ";
256	            cur += cw[ci]; ci++;
257	          } else break;
258	        }
259	        cl.push_back(cur);
260	      }
261	      if (ci < cw.size() && !cl.empty()) cl.back() += u"...";
262	      Page pg; pg.ctx = true;
263	      for (auto& s : cl) {
264	        if (!trim16(s).empty()) pg.lines.push_back({s, false});
265	      }
266	      if (!pg.lines.empty()) pages.push_back(pg);
267	    }
268	  }
269	  return pages;
270	}
