280	// ------------------------------------------------------------------ drawing helpers
281	static uint16_t hsl565(float h, float s, float l) {
282	  h = fmodf(h, 360.f); if (h < 0) h += 360.f;
283	  float c = (1 - fabsf(2 * l - 1)) * s;
284	  float x = c * (1 - fabsf(fmodf(h / 60.f, 2) - 1));
285	  float m = l - c / 2, r = 0, g = 0, b = 0;
286	  if (h < 60) { r = c; g = x; }
287	  else if (h < 120) { r = x; g = c; }
288	  else if (h < 180) { g = c; b = x; }
289	  else if (h < 240) { g = x; b = c; }
290	  else if (h < 300) { r = x; b = c; }
291	  else { r = c; b = x; }
292	  return rgb565((r + m) * 255, (g + m) * 255, (b + m) * 255);
293	}
294	
295	static float tagHue(const String& tag, int idx) {
296	  int32_t hash = 0;
297	  for (size_t i = 0; i < tag.length(); i++)
298	    hash = (int32_t)((((uint32_t)hash << 5) - (uint32_t)hash) + (uint8_t)tag[i]);
299	  return fabsf(floorf(fmodf((float)((double)hash * 137.508 + idx * 89), 360.f)));
300	}
