314	static void drawHeader(const Quote& q, bool busy) {
315	  cv.h = HDR_H;
316	  cv.fill(C_BLACK);
317	  cv.rect(0, HDR_H - 1, SW, 1, C_RULE);
318	  const int base = 14;
319	  std::u16string date = u8to16(q.date.length() ? q.date : String("—"));
320	  int dateW = fSB10.adv * (int)date.size();
321	  int labelW = fSB10.adv * 5;
322	  int rightW = labelW + 4 + dateW;
323	  int rx = SW - 12 - rightW;
324	  cv.text(fSB10, rx, base, u"Date:", C_DIM);
325	  cv.text(fSB10, rx + labelW + 4, base, date, C_GHOST);
326	  int x = 12;
327	  if (busy) {
328	    cv.text(fSB10, x, base, u"// Receiving prescript...", C_GHOST);
329	  } else {
330	    std::u16string idx = u"#" + u8to16(q.idx);
331	    x += cv.text(fBD13, x, base, idx, C_GHOST) + 4;
332	    x += cv.text(fSB10, x, base, u"~", C_SEP) + 4;
333	    std::u16string title = u8to16(q.specific);
334	    int avail = rx - 8 - x;
335	    int maxCh = avail / fSB10.adv;
336	    if ((int)title.size() > maxCh && maxCh > 1) title = title.substr(0, maxCh - 1) + u"\u2026";
337	    cv.text(fSB10, x, base, title, C_TITLE, avail);
338	  }
339	  push(0, HDR_H);
340	}
