342	static void drawFooter(const Quote& q, int seed = 0) {
343	  cv.h = FTR_H;
344	  cv.fill(C_BLACK);
345	  cv.rect(0, 0, SW, 1, C_RULE);
346	  uint16_t accent = accentFor(q);
347	  const int base = 15;
348	  std::u16string cont = u8to16(q.container);
349	  int contMax = 150 / fSB10.adv;
350	  if ((int)cont.size() > contMax) cont = cont.substr(0, contMax - 1) + u"\u2026";
351	  int contW = fSB10.adv * (int)cont.size();
352	  int cx = SW - 12 - contW;
353	  cv.text(fBD13, cx, base, cont, accent);
354	  int x = 12;
355	  for (size_t i = 0; i < q.tags.size(); i++) {
356	    std::u16string t = u8to16(q.tags[i]);
357	    int w = fSB9.adv * (int)t.size() + 10 + 2;
358	    if (x + w > cx - 8) break;
359	    float hue = tagHue(q.tags[i], (int)i) + seed;
360	    uint16_t tcol = hsl565(hue, 0.90f, 0.80f), bg = hsl565(hue, 0.65f, 0.12f);
361	    uint16_t bd = mix565(C_BLACK, hsl565(hue, 0.75f, 0.50f), 140);
362	    const int y0 = 4, hh = 15;
363	    cv.rect(x, y0, w, hh, bd);
364	    cv.rect(x + 1, y0 + 1, w - 2, hh - 2, bg);
365	    cv.b[y0 * cv.w + x] = C_BLACK; cv.b[y0 * cv.w + x + w - 1] = C_BLACK;
366	    cv.b[(y0 + hh - 1) * cv.w + x] = C_BLACK; cv.b[(y0 + hh - 1) * cv.w + x + w - 1] = C_BLACK;
367	    cv.text(fSB9, x + 6, y0 + 11, t, tcol);
368	    x += w + 4;
369	  }
370	  push(SH - FTR_H, FTR_H);
371	}
