373	// ------------------------------------------------------------------ page rendering
374	static int bodyTop(int n) {
375	  int blockH = n * LINE_PITCH - 2;
376	  int y = BODY_Y + (BODY_H - blockH) / 2;
377	  return y < BODY_Y ? BODY_Y : y;
378	}
379	
380	static void clearBody() {
381	  tft.startWrite();
382	  tft.fillRect(0, BODY_Y, SW, BODY_H, C_BLACK);
383	  tft.endWrite();
384	}
385	
386	static void drawBodyLineFinal(const Line& ln, int y, bool ctx, uint16_t accent) {
387	  cv.h = 20;
388	  cv.fill(ctx ? C_BOXBG : C_BLACK);
389	  const VFont& fn = fBD13;
390	  int base = (20 - (fn.ascent + fn.descent)) / 2 + fn.ascent;
391	  int cellW = fn.adv;
392	  int x0 = ctx ? 16 : 16;
393	  if (ctx) cv.rect(8, 0, 3, 20, accent);
394	  const std::u16string& s = ln.t;
395	  std::vector<int> xs(s.size());
396	  int spaces = 0;
397	  for (char16_t c : s) if (c == ' ') spaces++;
398	  if (ln.just && spaces > 0) {
399	    int W = MAX_CHARS * cellW;
400	    int gap = W - (int)(s.size() - spaces) * cellW;
401	    int extra = gap - spaces * 0;
402	    int per = extra / spaces, rem = extra % spaces, x = x0, sp = 0;
403	    for (size_t i = 0; i < s.size(); i++) {
404	      xs[i] = x;
405	      if (s[i] == ' ') x += per + (sp++ < rem ? 1 : 0);
406	      else x += cellW;
407	    }
408	  } else {
409	    for (size_t i = 0; i < s.size(); i++) xs[i] = x0 + (int)i * cellW;
410	  }
411	  for (size_t i = 0; i < s.size(); i++) {
412	    char16_t c = s[i];
413	    if (c == ' ') continue;
414	    if (ctx) {
415	      if (i < 6 && s.size() >= 6 && s.substr(0, 6) == u"[Note]") {
416	        cv.drawChar(fBD13, xs[i], base, c, accent, true); // Bilevel 1-bit crisp
417	      } else {
418	        cv.drawChar(fBD13, xs[i], base, c, C_WHITE, true);  // Bilevel 1-bit crisp
419	      }
420	    } else {
421	      if (c == 0x201C || c == 0x201D || c == '.') cv.drawChar(fBD13, xs[i], base, c, accent);
422	      else cv.drawChar(fn, xs[i], base, c, C_WHITE);
423	    }
424	  }
425	  push(y, 20);
426	}
