428	static void renderPageFinal(const Page& pg, uint16_t accent) {
429	  clearBody();
430	  int y = bodyTop((int)pg.lines.size());
431	  for (size_t i = 0; i < pg.lines.size(); i++) drawBodyLineFinal(pg.lines[i], y + (int)i * LINE_PITCH, pg.ctx, accent);
432	}
