434	// ------------------------------------------------------------------ entropy animation
435	struct Cell { char16_t target, cur; uint32_t life, nextScr; bool locked; };
436	static Cell grid[MAX_LINES][MAX_CHARS + 8];
437	static int gridLen[MAX_LINES];
438	static const char SCRAMBLE[] = "ABCDEF@HIJ_LM%OPQR^WX#YZa#b+cdefgh*iqrxyz0123456789!$*+=-~?/";
439	static char16_t rndCipher() { return SCRAMBLE[random(sizeof(SCRAMBLE) - 1)]; }
440	
441	// ------------------------------------------------------------------ state
442	static std::vector<Page> pages;
443	static int curPage = 0;
444	static bool animating = false;
445	static uint32_t animStart = 0, lastFrame = 0, nextChime = 0;
446	static uint16_t curAccent = ACCENTS[0];
447	
448	static uint32_t animFrameCount = 0;
449	
450	static void finishAnimation(bool playChime) {
451	  animating = false;
452	  nextChime = 0xFFFFFFFF;
453	  Serial.printf("[anim] FINISH at %u ms (%u frames, playChime=%d)\n", millis() - animStart, animFrameCount, playChime);
454	  renderPageFinal(pages[curPage], curAccent);
455	  drawHeader(quotes[curQuote], false);
456	  if (playChime) jqPlay(TRACK_COMPLETE);
457	}
