459	static bool renderAnimationFrame(uint32_t el) {
460	  Page& pg = pages[curPage];
461	  bool all = true;
462	  int y = bodyTop((int)pg.lines.size());
463	  const int base = (20 - (fBD13.ascent + fBD13.descent)) / 2 + fBD13.ascent;
464	
465	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
466	    cv.h = 20;
467	    cv.fill(C_BLACK);
468	    for (int c = 0; c < gridLen[r]; c++) {
469	      Cell& ce = grid[r][c];
470	      if (!ce.locked) {
471	        if (el >= ce.life) {
472	          ce.locked = true;
473	          ce.cur = ce.target;
474	        } else {
475	          all = false;
476	          // Active continuous cipher scramble on every frame
477	          ce.cur = rndCipher();
478	        }
479	      }
480	      int x = 16 + c * fBD13.adv;
481	      if (ce.locked) {
482	        if (ce.target == ' ') continue;
483	        if (ce.target == 0x201C || ce.target == 0x201D || ce.target == '.')
484	          cv.drawChar(fBD13, x, base, ce.target, curAccent);
485	        else
486	          cv.drawChar(fBD13, x, base, ce.target, C_WHITE);
487	      } else {
488	        cv.drawChar(fBD13, x, base, ce.cur, C_WHITE);
489	      }
490	    }
491	    push(y + r * LINE_PITCH, 20);
492	  }
493	  return all;
494	}
