510	  clearBody();
511	  uint32_t total = max<uint32_t>(900, ENTROPY_MS * 35);
512	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
513	    const std::u16string& s = pg.lines[r].t;
