515	    for (int c = 0; c < gridLen[r]; c++)
516	      grid[r][c] = {s[c], rndCipher(), (uint32_t)random(total), (uint32_t)random(40), false};
517	  }
518	  animating = true;
519	  animFrameCount = 0;
520	  Serial.printf("[anim] START Quote #%s (total=%u ms)\n", q.idx.c_str(), total);
521	
522	  // Instantly render Frame 0 of scramble — zero black void
523	  renderAnimationFrame(0);
524	
525	  if (sound) jqPlay(TRACK_DRAW);
526	
527	  // Time base begins strictly after initial frame is dispatched to screen
528	  animStart = millis();
529	  lastFrame = animStart;
530	}
